import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';
import * as moment from 'moment';
import { DateDisplay, JDate, JDateRecord } from "../../../../rt/interfaces/marknav.interface";

@Component({
  selector: 'date-show',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './date-show.component.html',
  styleUrls: ['./date-show.component.scss']
})
export class DateShowComponent {

  private DATE_ONLY_RE = /^\d{4}-\d{2}-\d{2}$/;

  // computed for template
  datePrefix: DateDisplay['prefix'] = 'On';
  isRange = false;
  dateText1 = '';
  dateText2 = '';

  @Input() jDate: JDate;
  @Input() showPrefix: boolean = true;

  ngOnInit() {
    const display = this.formatJDate(this.jDate as JDate);
    this.datePrefix = display.prefix;
    this.isRange = display.isRange;
    this.dateText1 = display.text1;
    this.dateText2 = display.text2 || '';
  }

  private formatJDate(jDate: JDate): DateDisplay {
    try {
      if (!jDate) return { prefix: 'On', isRange: false, text1: '', text2: '' };
      const monthNames = moment.monthsShort();

      const safeMonth = (m?: string) => {
        const n = Number(m);
        return isFinite(n) && n >= 1 && n <= 12 ? monthNames[n - 1] : '';
      };

      // ✅ Always show in M/D/YYYY, h:mm:ss A (e.g. 12/29/2025, 2:53:22 AM)
      const fmtFull = (raw?: string) => {
        if (!raw) return '';
        if (this.DATE_ONLY_RE.test(raw)) {
          return moment.utc(raw, 'YYYY-MM-DD', true).format('M/D/YYYY, h:mm:ss A');
        }
        return moment.parseZone(raw).local().format('M/D/YYYY, h:mm:ss A');
      };

      const toMY = (r?: JDateRecord) => {
        if (!r) return '';
        const y = r.year || '';
        const m = safeMonth(r.month);
        if (m && y) return `${m}, ${y}`;
        if (y) return y;
        return '';
      };

      const prefixFromCValue = (cv: string, isRange: boolean): DateDisplay['prefix'] => {
        if (cv === 'Between' || isRange) return 'From to';
        return cv as DateDisplay['prefix'];
      };

      const rec = (jDate.record || []).slice(0, 2);
      const r1 = rec[0];
      const r2 = rec[1];

      let text1 = '';
      let text2 = '';
      let isRange = false;

      if (jDate.type === 'D') {
        const d1 = fmtFull(r1?.date);
        const d2 = fmtFull(r2?.date);
        if (d1 && d2) {
          isRange = d1 !== d2;
          text1 = d1;
          text2 = isRange ? d2 : '';
        } else {
          text1 = d1 || d2 || '';
        }
      } else if (jDate.type === 'MY') {
        const m1 = toMY(r1);
        const m2 = toMY(r2);
        if (m1 && m2) {
          isRange = m1 !== m2;
          text1 = m1;
          text2 = isRange ? m2 : '';
        } else {
          text1 = m1 || m2 || '';
        }
      } else if (jDate.type === 'Y') {
        const y1 = r1?.year || '';
        const y2 = r2?.year || '';
        if (y1 && y2) {
          isRange = y1 !== y2;
          text1 = y1;
          text2 = isRange ? y2 : '';
        } else {
          text1 = y1 || y2 || '';
        }
      }

      const prefix = prefixFromCValue(jDate.cValue, isRange);
      return { prefix, isRange, text1, text2: isRange ? text2 : undefined };
    } catch {
      return { prefix: 'On', isRange: false, text1: '', text2: '' };
    }
  }

}
